import{_ as a,o as r,c as e,ai as o}from"./chunks/framework.CGsC_gYW.js";const p=JSON.parse('{"title":"插件定制","description":"","frontmatter":{"title":"插件定制"},"headers":[],"relativePath":"custom.md","filePath":"custom.md","lastUpdated":1792576248000}'),i={name:"custom.md"};function l(d,t,n,s,h,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="插件定制" tabindex="-1">插件定制 <a class="header-anchor" href="#插件定制" aria-label="Permalink to &quot;插件定制&quot;">​</a></h1><blockquote><p>接所有版本的 Minecraft 服务端插件定制。1.7.10 到最新版，Spigot / Paper / 混合端都做过。 不转包，不套模板，代码和文档一起交付。</p></blockquote><h2 id="先说清楚三件事" tabindex="-1">先说清楚三件事 <a class="header-anchor" href="#先说清楚三件事" aria-label="Permalink to &quot;先说清楚三件事&quot;">​</a></h2><p><strong>一、需求越具体，报价越准。</strong> 「做个抽奖」和「做个十连保底、概率公示、奖池分时段、抽完上全服广播的抽奖」是两个工作量。前者一句话能开工，后者得先对需求。</p><p><strong>二、能做和不能做都会直说。</strong> 有些需求用现成插件改配置就能解决，没必要花钱写新的，我会直接告诉你。做不到的也说做不到，不接了自己也难受。</p><p><strong>三、交付的不只是 jar。</strong> 一个只有 jar 的插件，换个人接手就是黑盒。所以配置、文档、指令权限表是默认交付项，不是加钱项。</p><h2 id="常做的类型" tabindex="-1">常做的类型 <a class="header-anchor" href="#常做的类型" aria-label="Permalink to &quot;常做的类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>举例</th></tr></thead><tbody><tr><td>签到 / 福利</td><td>每日签到、在线奖励、累计在线、兑换码</td></tr><tr><td>抽奖 / 氪金</td><td>转盘、盲盒、保底抽卡、概率公示、限时池</td></tr><tr><td>副本 / 玩法</td><td>自定义副本、波次刷怪、BOSS 战、限时活动</td></tr><tr><td>经济 / 商店</td><td>点券系统、GUI 商店、拍卖行、回收站</td></tr><tr><td>数据 / 统计</td><td>玩家数据面板、排行榜、战绩统计、数据看板</td></tr><tr><td>服管工具</td><td>封禁申诉、举报、工单、自动公告、活动配置化</td></tr></tbody></table><h2 id="交付清单" tabindex="-1">交付清单 <a class="header-anchor" href="#交付清单" aria-label="Permalink to &quot;交付清单&quot;">​</a></h2><ul><li>可运行的 jar，适配你指定的服务端版本</li><li>完整 <code>config.yml</code>：奖励、数值、文案、音效全部可改，不用来找我改代码</li><li>部署与配置文档，和这个站点里的文档同规格</li><li>上线后的问题修复；改动大的需求按阶段走</li></ul><h2 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h2><ol><li><strong>对需求</strong>：玩法、数值、界面、依赖哪些插件，一次说清</li><li><strong>出方案</strong>：功能清单、配置结构、工期和报价，确认后再动手</li><li><strong>开发联调</strong>：按阶段给测试包，你在自己服上跑</li><li><strong>交付上线</strong>：jar + 配置 + 文档，出问题随时找</li></ol><h2 id="已有成品" tabindex="-1">已有成品 <a class="header-anchor" href="#已有成品" aria-label="Permalink to &quot;已有成品&quot;">​</a></h2><ul><li><a href="/plugin-wiki/qiantao/">[klkhk]plugin_qiandao_1.12.2</a> — 七日周期 / 补签卡 / 排行榜 / 经济联动，Minecraft 1.12.2</li></ul><h2 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h2><ul><li><strong>QQ</strong>：<code>1071576270</code></li><li><strong>邮箱</strong>：<code>1071576270@qq.com</code></li></ul><p>加好友备注一下来意，比如「定制 + 抽奖」或「定制 + 副本」，我好提前想方案。</p><hr><p><a href="/plugin-wiki/">返回首页</a> · <a href="/plugin-wiki/plugins">插件库</a></p>',19)])])}const g=a(i,[["render",l]]);export{p as __pageData,g as default};
